<script lang="ts">
  import { About, Button, Modal, PageHeader, Select, SettingsRow, SettingsSection } from '@etzianco/ui';
  import { onMount } from 'svelte';

  import { DangerZone } from '../legal-ux';
  import { getLocale, t } from '../i18n';
  import { appInfo } from '../ipc/app';
  import { applyDensity, applyLanguage, applyTheme, eraseLocalData, settings, type Density, type Language, type ThemePreference } from '../stores/settings.svelte';

  // Generated by `ez legal gen`; rebuilt with the app. Drafts until a lawyer reviews the templates.
  const docs: Record<string, Record<string, string>> = {
    'fr-CA': {
      privacy: Object.values(import.meta.glob('../../../../legal/generated/fr-CA/privacy-policy.md', { query: '?raw', import: 'default', eager: true }))[0] as string,
      terms: Object.values(import.meta.glob('../../../../legal/generated/fr-CA/terms-of-use.md', { query: '?raw', import: 'default', eager: true }))[0] as string
    },
    en: {
      privacy: Object.values(import.meta.glob('../../../../legal/generated/en/privacy-policy.md', { query: '?raw', import: 'default', eager: true }))[0] as string,
      terms: Object.values(import.meta.glob('../../../../legal/generated/en/terms-of-use.md', { query: '?raw', import: 'default', eager: true }))[0] as string
    }
  };

  let version = $state('');
  let openDoc = $state<'privacy' | 'terms' | null>(null);

  onMount(() => {
    appInfo().then((i) => (version = i.version)).catch(() => {});
  });

  const languages = $derived([
    { value: 'system', label: t('settings-language-system') },
    { value: 'fr-CA', label: t('settings-language-fr-ca') },
    { value: 'en', label: t('settings-language-en') }
  ]);
  const themes = $derived([
    { value: 'auto', label: t('settings-theme-system') },
    { value: 'light', label: t('settings-theme-light') },
    { value: 'dark', label: t('settings-theme-dark') }
  ]);
  const densities = $derived([
    { value: 'comfortable', label: t('settings-density-comfortable') },
    { value: 'compact', label: t('settings-density-compact') }
  ]);
  const deleted = $derived([t('erase-item-settings')]);
  const year = $derived(new Date().getFullYear());
  const title = $derived(openDoc === 'privacy' ? t('legal-privacy-policy') : t('legal-terms-of-use'));
</script>

<div class="app-page">
  <PageHeader title={t('settings-title')} />

  <SettingsSection title={t('settings-section-language')}>
    <Select label={t('settings-language-label')} placeholder="" value={settings.language} options={languages} onchange={(e: Event) => applyLanguage((e.target as HTMLSelectElement).value as Language)} />
  </SettingsSection>

  <SettingsSection title={t('settings-section-appearance')}>
    <Select label={t('settings-theme-label')} placeholder="" value={settings.theme} options={themes} onchange={(e: Event) => applyTheme((e.target as HTMLSelectElement).value as ThemePreference)} />
    <Select label={t('settings-density-label')} placeholder="" value={settings.density} options={densities} onchange={(e: Event) => applyDensity((e.target as HTMLSelectElement).value as Density)} />
  </SettingsSection>

  <SettingsSection title={t('settings-section-privacy')} description={t('settings-privacy-description')}>
    <SettingsRow label={t('legal-privacy-policy')}><Button variant="secondary" onclick={() => (openDoc = 'privacy')}>{t('privacy-policy-open')}</Button></SettingsRow>
    <SettingsRow label={t('legal-terms-of-use')}><Button variant="secondary" onclick={() => (openDoc = 'terms')}>{t('privacy-policy-open')}</Button></SettingsRow>
  </SettingsSection>

  <About
    name={t('app-name')}
    version={version ? t('about-version', { version }) : ''}
    versionLabel=""
    endorsedBy={t('about-endorsed-by')}
    copyright={t('about-copyright', { year: String(year), company: t('company-name') })}
  />

  <DangerZone kind="local-data" {t} {deleted} ondelete={eraseLocalData} />
</div>

<Modal open={openDoc !== null} {title} onclose={() => (openDoc = null)}>
  <pre class="app-doc" lang={getLocale()}>{openDoc ? docs[getLocale()][openDoc] : ''}</pre>
</Modal>
